/*
================================================================================
  LOCAL ONLY. NOT FOR ANY SHARED DATABASE. Tri-AP sample data (Phase 6, T6.12).
  INVENTED data for a developer's own database. Refuses to run against Azure SQL
  (see the guard below); run against the local Docker database only, after
  create-finance-schema.sql, create-finance-access-schema.sql, create-finance-
  attachments-schema.sql, create-finance-invoice-schema.sql, create-finance-odoo-
  schema.sql, seed-finance-ap-permissions.sql, seed-finance-ap-roles.sql and
  seed-finance-mailboxes-local.sql. Applying it to tricab-mel is forbidden.

  So that every Tri-AP page has something to show on a laptop (the browser check
  of FINANCE-PHASE-6-WEB.md, and the reference screenshots, question Q15):

      32 invoices (28 live, 4 in the Bin) over the last 60 days, in every stored
      status, four of them Overdue on any day this is run; the three duplicate
      states; low-confidence ones with the reason the API writes; every vendor
      match (and none); hand captures as well as scanned ones; 22 with a document
      (20 PDFs and 2 PNG photos), the rest without; every approval status;
      26 scanned emails in two mailboxes (Invoice and Other, Verified, Unverified
      and Needs review, one in the Bin, one with a proposed reply) and their
      attachments, one of them an exact copy of an invoice already filed;
      3 scan runs (two complete and one failed, none left open: an open one would
      block scanning) and one skipped-attachment tombstone;
      3 approval batches (Pending, Approved, Rejected) with items and decisions;
      5 sent-mail rows (vendor emails, replies and an approval request; sent and
      failed); 10 audit events; 13 Odoo vendors (2 archived) and one successful
      sync run; 4 companies, 6 cost centres, 7 account categories and 6 signing
      limits (one unlimited, some with no authority for a document type).

  Invented throughout: vendors, senders (example.test), invoices, amounts and
  documents. The people are the local test users Tri-AR's and Tri-Task's sample
  seeds create (@sample.local), made if missing, so the samples can be applied in
  any order. Each gets a Tri-AP role:

      sample.admin@sample.local   Administrator (every mailbox)
      lena.marsh@sample.local     Operator
      mia.ford@sample.local       Preparer
      owen.reed@sample.local      Approver
      noah.hale@sample.local      Operator, scoped to ap.projects@sample.local only

  The documents' bytes are NOT in this script: they are made by
  src/Finance/Ap/ApSampleFiles.php and loaded into the in-memory blob store when
  FINANCE_AP_SAMPLE_FILES=true (development only). The rows here name each file's
  blob path, size and SHA-256, the invoice carries the same SHA-256, and
  FinanceApSampleSeedScriptTest pins that they match that class.

  Dates are relative to the run: due dates to today in Australia/Melbourne, times
  to the moment it is run (or the start of that local day), so "Overdue" stays
  overdue and the register's Today, This week and This month are never empty.

  Idempotent: every row has a fixed id and is inserted only if missing, so running
  it twice adds nothing. It never changes a row that exists. One transaction.
================================================================================
*/

SET NOCOUNT ON;
SET XACT_ABORT ON;

/* ---------------------------------------------------------------------------
   Guard: local SQL Server only. Azure SQL Database, Managed Instance and Azure
   Synapse report engine editions 5, 8 and 6; the local Docker server is 3
   (Enterprise and Developer), 2 (Standard) or 4 (Express).
   --------------------------------------------------------------------------- */
IF CAST(SERVERPROPERTY('EngineEdition') AS INT) NOT IN (2, 3, 4)
   OR @@SERVERNAME LIKE N'%database.windows.net%'
   OR @@SERVERNAME LIKE N'%tricab-mel%'
BEGIN
    THROW 54240, N'The Tri-AP sample seed is for the local Docker database only. Refusing to run against Azure SQL.', 1;
END;
IF OBJECT_ID(N'[finance].[invoice_invoices]', N'U') IS NULL
   OR OBJECT_ID(N'[finance].[attachments]', N'U') IS NULL
   OR OBJECT_ID(N'[finance].[mail_deliveries]', N'U') IS NULL
   OR OBJECT_ID(N'[finance].[mailboxes]', N'U') IS NULL
   OR OBJECT_ID(N'[finance].[access_scopes]', N'U') IS NULL
   OR OBJECT_ID(N'[finance].[odoo_records]', N'U') IS NULL
   OR OBJECT_ID(N'[identity].[Users]', N'U') IS NULL
BEGIN
    THROW 54241, N'Run the finance schemas (create-finance-schema.sql, -access-, -attachments-, -invoice-, -odoo-) and the identity schema first.', 1;
END;

BEGIN TRY
    BEGIN TRANSACTION;

    DECLARE @Today DATE = CAST(SYSDATETIMEOFFSET() AT TIME ZONE N'AUS Eastern Standard Time' AS DATE);
    DECLARE @Now DATETIME2(6) = SYSUTCDATETIME();
    /* The instant (UTC) at which today began in Australia/Melbourne. */
    DECLARE @TodayStart DATETIME2(6) = CAST((CAST(@Today AS DATETIME2(6)) AT TIME ZONE N'AUS Eastern Standard Time') AT TIME ZONE N'UTC' AS DATETIME2(6));

    /* ------------------------------------------------------------------
       People: five local test users and their Tri-AP roles.
       ------------------------------------------------------------------ */
    DECLARE @People TABLE (
        [Key]       NVARCHAR(20)  NOT NULL PRIMARY KEY,
        [Email]     NVARCHAR(256) NOT NULL,
        [Name]      NVARCHAR(200) NOT NULL,
        [RoleCode]  NVARCHAR(100) NOT NULL
    );
    INSERT INTO @People ([Key], [Email], [Name], [RoleCode]) VALUES
        (N'admin', N'sample.admin@sample.local', N'Sample Administrator', N'FINANCE_AP_ADMIN'),
        (N'lena',  N'lena.marsh@sample.local',   N'Lena Marsh',           N'FINANCE_AP_OPERATOR'),
        (N'mia',   N'mia.ford@sample.local',     N'Mia Ford',             N'FINANCE_AP_PREPARER'),
        (N'owen',  N'owen.reed@sample.local',    N'Owen Reed',            N'FINANCE_AP_APPROVER'),
        (N'noah',  N'noah.hale@sample.local',    N'Noah Hale',            N'FINANCE_AP_OPERATOR');

    INSERT INTO [identity].[Users] ([EmailAddress], [NormalizedEmailAddress], [DisplayName], [UserStatusId])
    SELECT p.[Email], LOWER(p.[Email]), p.[Name], s.[UserStatusId]
    FROM @People p
    CROSS JOIN [identity].[UserStatuses] s
    WHERE s.[StatusCode] = N'active'
      AND NOT EXISTS (SELECT 1 FROM [identity].[Users] u WHERE u.[NormalizedEmailAddress] = LOWER(p.[Email]));

    INSERT INTO [identity].[UserRoles] ([UserId], [RoleId], [IsActive])
    SELECT u.[UserId], r.[RoleId], 1
    FROM @People p
    JOIN [identity].[Users] u ON u.[NormalizedEmailAddress] = LOWER(p.[Email])
    JOIN [identity].[Roles] r ON UPPER(r.[RoleCode]) = p.[RoleCode]
    WHERE NOT EXISTS (SELECT 1 FROM [identity].[UserRoles] ur WHERE ur.[UserId] = u.[UserId] AND ur.[RoleId] = r.[RoleId]);

    IF (SELECT COUNT(*) FROM @People p
         JOIN [identity].[Users] u ON u.[NormalizedEmailAddress] = LOWER(p.[Email])
         JOIN [identity].[UserRoles] ur ON ur.[UserId] = u.[UserId] AND ur.[IsActive] = 1
         JOIN [identity].[Roles] r ON r.[RoleId] = ur.[RoleId] AND UPPER(r.[RoleCode]) = p.[RoleCode]) < 5
    BEGIN
        THROW 54242, N'The Tri-AP roles are missing. Run seed-finance-ap-permissions.sql and seed-finance-ap-roles.sql first.', 1;
    END;

    DECLARE @Ids TABLE ([Key] NVARCHAR(20) NOT NULL PRIMARY KEY, [UserId] BIGINT NOT NULL, [Name] NVARCHAR(200) NOT NULL, [Email] NVARCHAR(256) NOT NULL);
    INSERT INTO @Ids ([Key], [UserId], [Name], [Email])
    SELECT p.[Key], u.[UserId], u.[DisplayName], u.[NormalizedEmailAddress] FROM @People p JOIN [identity].[Users] u ON u.[NormalizedEmailAddress] = LOWER(p.[Email]);

    /* ------------------------------------------------------------------
       Mailboxes: ap@tricab.com is the one seed-finance-mailboxes-local.sql makes
       (the same id, so either order works); a second, ap.projects@sample.local,
       lets the mailbox tabs and a person's scope be seen. Both read and send for AP.
       ------------------------------------------------------------------ */
    INSERT INTO [finance].[mailboxes] ([id], [email], [display_name], [purpose], [is_active])
    SELECT v.[id], v.[email], v.[display_name], v.[purpose], 1
    FROM (VALUES
        ('0c1a0000000000000000000000000001', N'ap@tricab.com', N'Accounts Payable', N'Vendor invoices and AP approvals (local development row)'),
        ('a9110000000000000000000000000001', N'ap.projects@sample.local', N'AP Projects (sample)', N'Sample second AP mailbox (local development row)')
    ) v ([id], [email], [display_name], [purpose])
    WHERE NOT EXISTS (SELECT 1 FROM [finance].[mailboxes] e WHERE e.[email] = v.[email]);

    INSERT INTO [finance].[mailbox_grants] ([id], [application_key], [mailbox_id], [can_read], [can_send])
    SELECT v.[id], N'AP', mb.[id], 1, 1
    FROM (VALUES
        ('0c1b0000000000000000000000000001', N'ap@tricab.com'),
        ('a9120000000000000000000000000001', N'ap.projects@sample.local')
    ) v ([id], [email])
    JOIN [finance].[mailboxes] mb ON mb.[email] = v.[email]
    WHERE NOT EXISTS (SELECT 1 FROM [finance].[mailbox_grants] g WHERE g.[application_key] = N'AP' AND g.[mailbox_id] = mb.[id]);

    /* Noah Hale sees only the second mailbox (and hand captures, which have none). */
    INSERT INTO [finance].[access_scopes] ([user_id], [application_key], [scope_type], [scope_value])
    SELECT i.[UserId], N'AP', N'mailbox', N'ap.projects@sample.local'
    FROM @Ids i
    WHERE i.[Key] = N'noah'
      AND NOT EXISTS (SELECT 1 FROM [finance].[access_scopes] s WHERE s.[user_id] = i.[UserId] AND s.[application_key] = N'AP' AND s.[scope_type] = N'mailbox' AND s.[scope_value] = N'ap.projects@sample.local');

    /* ------------------------------------------------------------------
       Settings lists and signing authority.
       ------------------------------------------------------------------ */
    INSERT INTO [finance].[invoice_companies]
        ([id], [code], [name], [sites], [former_names], [is_active], [created_date])
    SELECT v.[id], v.[code], v.[name], v.[sites], v.[former_names], v.[is_active], v.[created_date]
    FROM (VALUES
        ('a90d0000000000000000000000000001', N'HVT', N'Harbourview Trading Pty Ltd', N'Melbourne; Sydney', N'Harbourview Wholesale Pty Ltd', 1, DATEADD(MINUTE, 600, DATEADD(DAY, -60, @TodayStart))),
        ('a90d0000000000000000000000000002', N'NFC', N'Northfield Cables NZ Ltd', N'Auckland', N'', 1, DATEADD(MINUTE, 600, DATEADD(DAY, -60, @TodayStart))),
        ('a90d0000000000000000000000000003', N'MRD', N'Meridian Components Pty Ltd', N'Brisbane; Perth', N'Meridian Parts Pty Ltd; Meridian Holdings', 1, DATEADD(MINUTE, 600, DATEADD(DAY, -60, @TodayStart))),
        ('a90d0000000000000000000000000004', N'SGD', N'Sandgate Distribution Pty Ltd', N'Adelaide', N'Sandgate Freight', 0, DATEADD(MINUTE, 600, DATEADD(DAY, -60, @TodayStart)))
    ) v ([id], [code], [name], [sites], [former_names], [is_active], [created_date])
    WHERE NOT EXISTS (SELECT 1 FROM [finance].[invoice_companies] x WHERE x.[id] = v.[id] OR x.[name] = v.[name]);

    INSERT INTO [finance].[invoice_cost_centres]
        ([id], [code_no], [code], [name], [is_active], [created_date])
    SELECT v.[id], v.[code_no], v.[code], v.[name], v.[is_active], v.[created_date]
    FROM (VALUES
        ('a90e0000000000000000000000000001', N'1000', N'CC-100', N'Head Office', 1, DATEADD(MINUTE, 600, DATEADD(DAY, -60, @TodayStart))),
        ('a90e0000000000000000000000000002', N'2100', N'CC-210', N'Melbourne Warehouse', 1, DATEADD(MINUTE, 600, DATEADD(DAY, -60, @TodayStart))),
        ('a90e0000000000000000000000000003', N'3100', N'CC-310', N'Brisbane Sales', 1, DATEADD(MINUTE, 600, DATEADD(DAY, -60, @TodayStart))),
        ('a90e0000000000000000000000000004', N'4100', N'CC-410', N'Information Technology', 1, DATEADD(MINUTE, 600, DATEADD(DAY, -60, @TodayStart))),
        ('a90e0000000000000000000000000005', N'5100', N'CC-510', N'Auckland Operations', 1, DATEADD(MINUTE, 600, DATEADD(DAY, -60, @TodayStart))),
        ('a90e0000000000000000000000000006', N'9900', N'CC-990', N'Closed Project (retired)', 0, DATEADD(MINUTE, 600, DATEADD(DAY, -60, @TodayStart)))
    ) v ([id], [code_no], [code], [name], [is_active], [created_date])
    WHERE NOT EXISTS (SELECT 1 FROM [finance].[invoice_cost_centres] x WHERE x.[id] = v.[id] OR x.[code] = v.[code]);

    INSERT INTO [finance].[invoice_account_categories]
        ([id], [code], [name], [is_active], [created_date])
    SELECT v.[id], v.[code], v.[name], v.[is_active], v.[created_date]
    FROM (VALUES
        ('a90f0000000000000000000000000001', N'AC-FREIGHT', N'Freight and cartage', 1, DATEADD(MINUTE, 600, DATEADD(DAY, -60, @TodayStart))),
        ('a90f0000000000000000000000000002', N'AC-OFFICE', N'Office supplies', 1, DATEADD(MINUTE, 600, DATEADD(DAY, -60, @TodayStart))),
        ('a90f0000000000000000000000000003', N'AC-IT', N'IT and software', 1, DATEADD(MINUTE, 600, DATEADD(DAY, -60, @TodayStart))),
        ('a90f0000000000000000000000000004', N'AC-REPAIRS', N'Repairs and maintenance', 1, DATEADD(MINUTE, 600, DATEADD(DAY, -60, @TodayStart))),
        ('a90f0000000000000000000000000005', N'AC-PROF', N'Professional fees', 1, DATEADD(MINUTE, 600, DATEADD(DAY, -60, @TodayStart))),
        ('a90f0000000000000000000000000006', N'AC-UTIL', N'Utilities and cleaning', 1, DATEADD(MINUTE, 600, DATEADD(DAY, -60, @TodayStart))),
        ('a90f0000000000000000000000000007', N'AC-OLD', N'Old category (retired)', 0, DATEADD(MINUTE, 600, DATEADD(DAY, -60, @TodayStart)))
    ) v ([id], [code], [name], [is_active], [created_date])
    WHERE NOT EXISTS (SELECT 1 FROM [finance].[invoice_account_categories] x WHERE x.[id] = v.[id] OR x.[code] = v.[code]);

    /* 99999999999 is how the source writes "unlimited"; a NULL is no authority for that document type. */
    INSERT INTO [finance].[invoice_signing_limits]
        ([id], [authority_role], [role_code], [full_name], [email], [d365_position], [po_inventory], [po_non_inventory], [expense_claim], [customer_order], [credit_notes], [is_active], [created_date])
    SELECT v.[id], v.[authority_role], v.[role_code], v.[full_name], v.[email], v.[d365_position], v.[po_inventory], v.[po_non_inventory], v.[expense_claim], v.[customer_order], v.[credit_notes], v.[is_active], v.[created_date]
    FROM (VALUES
        ('a9100000000000000000000000000001', N'Chief Financial Officer', N'CFO', N'Rosa Wynn', N'rosa.wynn@sample.local', N'Chief Financial Officer', 99999999999.00, 99999999999.00, 99999999999.00, 99999999999.00, 99999999999.00, 1, DATEADD(MINUTE, 600, DATEADD(DAY, -60, @TodayStart))),
        ('a9100000000000000000000000000002', N'Finance Manager', N'FM', N'Theo Park', N'theo.park@sample.local', N'Finance Manager', 250000.00, 100000.00, 20000.00, 150000.00, 25000.00, 1, DATEADD(MINUTE, 600, DATEADD(DAY, -60, @TodayStart))),
        ('a9100000000000000000000000000003', N'Warehouse Supervisor', N'WS', N'Ivan Cole', N'ivan.cole@sample.local', N'Warehouse Supervisor', 50000.00, 10000.00, 2000.00, NULL, NULL, 1, DATEADD(MINUTE, 600, DATEADD(DAY, -60, @TodayStart))),
        ('a9100000000000000000000000000004', N'Sales Manager', N'SM', N'Ada Quinn', N'ada.quinn@sample.local', N'Sales Manager', NULL, 15000.00, 5000.00, 100000.00, 10000.00, 1, DATEADD(MINUTE, 600, DATEADD(DAY, -60, @TodayStart))),
        ('a9100000000000000000000000000005', N'Accounts Payable Lead', N'APL', N'Lena Marsh', N'lena.marsh@sample.local', N'Accounts Payable Lead', 25000.00, 25000.00, 5000.00, NULL, 5000.00, 1, DATEADD(MINUTE, 600, DATEADD(DAY, -60, @TodayStart))),
        ('a9100000000000000000000000000006', N'Acting Director (ended)', N'AD', N'Pat Example', N'', N'Acting Director', 500000.00, 500000.00, 50000.00, 500000.00, 50000.00, 0, DATEADD(MINUTE, 600, DATEADD(DAY, -60, @TodayStart)))
    ) v ([id], [authority_role], [role_code], [full_name], [email], [d365_position], [po_inventory], [po_non_inventory], [expense_claim], [customer_order], [credit_notes], [is_active], [created_date])
    WHERE NOT EXISTS (SELECT 1 FROM [finance].[invoice_signing_limits] x WHERE x.[id] = v.[id] OR x.[d365_position] = v.[d365_position]);

    /* ------------------------------------------------------------------
       The vendors (Odoo's res.partner copy, two archived) and the sync run that
       gives the Vendors page its "last synced" time.
       ------------------------------------------------------------------ */
    INSERT INTO [finance].[odoo_records]
        ([list_key], [odoo_id], [name], [code], [company_id], [is_active], [data_json], [write_date], [synced_at])
    SELECT v.[list_key], v.[odoo_id], v.[name], v.[code], v.[company_id], v.[is_active], v.[data_json], v.[write_date], v.[synced_at]
    FROM (VALUES
        (N'vendors', 101, N'Alder & Vale Logistics Pty Ltd', N'V-0101', 1, 1, N'{"name":"Alder & Vale Logistics Pty Ltd","ref":"V-0101","email":"accounts@alder-vale.example.test","vat":"51 000 000 101","phone":"+61 3 5550 0101","company_id":1,"company_name":"Harbourview Trading Pty Ltd","is_company":true,"parent_id":null,"parent_name":"","country":"Australia"}', DATEADD(DAY, -4, @Now), DATEADD(HOUR, -3, @Now)),
        (N'vendors', 102, N'Quillon Packaging Supplies', N'V-0102', 1, 1, N'{"name":"Quillon Packaging Supplies","ref":"V-0102","email":"accounts@quillon-packaging.example.test","vat":"51 000 000 102","phone":"+61 3 5550 0102","company_id":1,"company_name":"Harbourview Trading Pty Ltd","is_company":true,"parent_id":null,"parent_name":"","country":"Australia"}', DATEADD(DAY, -5, @Now), DATEADD(HOUR, -3, @Now)),
        (N'vendors', 103, N'Fernhill Industrial Supplies Pty Ltd', N'V-0103', 1, 1, N'{"name":"Fernhill Industrial Supplies Pty Ltd","ref":"V-0103","email":"billing@fernhill-industrial.example.test","vat":"51 000 000 103","phone":"+61 7 5550 0103","company_id":1,"company_name":"Meridian Components Pty Ltd","is_company":true,"parent_id":null,"parent_name":"","country":"Australia"}', DATEADD(DAY, -6, @Now), DATEADD(HOUR, -3, @Now)),
        (N'vendors', 104, N'Marlow Freight Services', N'V-0104', 1, 1, N'{"name":"Marlow Freight Services","ref":"V-0104","email":"accounts@marlow-freight.example.test","vat":"51 000 000 104","phone":"+61 2 5550 0104","company_id":1,"company_name":"Harbourview Trading Pty Ltd","is_company":true,"parent_id":null,"parent_name":"","country":"Australia"}', DATEADD(DAY, -7, @Now), DATEADD(HOUR, -3, @Now)),
        (N'vendors', 105, N'Orchard Lane Catering', N'V-0105', 1, 1, N'{"name":"Orchard Lane Catering","ref":"V-0105","email":"hello@orchardlane.example.test","vat":"51 000 000 105","phone":"+61 3 5550 0105","company_id":1,"company_name":"Harbourview Trading Pty Ltd","is_company":true,"parent_id":null,"parent_name":"","country":"Australia"}', DATEADD(DAY, -8, @Now), DATEADD(HOUR, -3, @Now)),
        (N'vendors', 106, N'Tallow Creek Engineering', N'V-0106', 1, 1, N'{"name":"Tallow Creek Engineering","ref":"V-0106","email":"accounts@tallowcreek.example.test","vat":"51 000 000 106","phone":"+61 8 5550 0106","company_id":1,"company_name":"Meridian Components Pty Ltd","is_company":true,"parent_id":null,"parent_name":"","country":"Australia"}', DATEADD(DAY, -9, @Now), DATEADD(HOUR, -3, @Now)),
        (N'vendors', 107, N'Brightwell Safety Equipment', N'V-0107', 1, 1, N'{"name":"Brightwell Safety Equipment","ref":"V-0107","email":"accounts@brightwell-safety.example.test","vat":"51 000 000 107","phone":"+61 3 5550 0107","company_id":1,"company_name":"Harbourview Trading Pty Ltd","is_company":true,"parent_id":null,"parent_name":"","country":"Australia"}', DATEADD(DAY, -10, @Now), DATEADD(HOUR, -3, @Now)),
        (N'vendors', 108, N'Sable Peak IT Services', N'V-0108', 1, 1, N'{"name":"Sable Peak IT Services","ref":"V-0108","email":"billing@sablepeak.example.test","vat":"51 000 000 108","phone":"+61 3 5550 0108","company_id":1,"company_name":"Harbourview Trading Pty Ltd","is_company":true,"parent_id":null,"parent_name":"","country":"Australia"}', DATEADD(DAY, -11, @Now), DATEADD(HOUR, -3, @Now)),
        (N'vendors', 109, N'Wombat Gully Electrical', N'V-0109', 1, 0, N'{"name":"Wombat Gully Electrical","ref":"V-0109","email":"admin@wombatgully.example.test","vat":"51 000 000 109","phone":"+61 3 5550 0109","company_id":1,"company_name":"Harbourview Trading Pty Ltd","is_company":true,"parent_id":null,"parent_name":"","country":"Australia"}', DATEADD(DAY, -12, @Now), DATEADD(HOUR, -3, @Now)),
        (N'vendors', 110, N'Pinecrest Cleaning Co', N'V-0110', 1, 0, N'{"name":"Pinecrest Cleaning Co","ref":"V-0110","email":"office@pinecrest-cleaning.example.test","vat":"51 000 000 110","phone":"+61 3 5550 0110","company_id":1,"company_name":"Harbourview Trading Pty Ltd","is_company":true,"parent_id":null,"parent_name":"","country":"Australia"}', DATEADD(DAY, -13, @Now), DATEADD(HOUR, -3, @Now)),
        (N'vendors', 111, N'Zephyr Metalworks', N'V-0111', 1, 1, N'{"name":"Zephyr Metalworks","ref":"V-0111","email":"sales@zephyrmetal.example.test","vat":"51 000 000 111","phone":"+61 3 5550 0111","company_id":1,"company_name":"Meridian Components Pty Ltd","is_company":true,"parent_id":null,"parent_name":"","country":"Australia"}', DATEADD(DAY, -14, @Now), DATEADD(HOUR, -3, @Now)),
        (N'vendors', 112, N'Kiwi Coast Couriers Ltd', N'V-0112', 2, 1, N'{"name":"Kiwi Coast Couriers Ltd","ref":"V-0112","email":"accounts@kiwicoast.example.test","vat":"NZ 000-000-112","phone":"+64 9 555 0112","company_id":2,"company_name":"Northfield Cables NZ Ltd","is_company":true,"parent_id":null,"parent_name":"","country":"New Zealand"}', DATEADD(DAY, -15, @Now), DATEADD(HOUR, -3, @Now)),
        (N'vendors', 113, N'Granite Hill Hardware', N'V-0113', 1, 1, N'{"name":"Granite Hill Hardware","ref":"V-0113","email":"trade@granitehill.example.test","vat":"51 000 000 113","phone":"+61 3 5550 0113","company_id":1,"company_name":"Harbourview Trading Pty Ltd","is_company":true,"parent_id":null,"parent_name":"","country":"Australia"}', DATEADD(DAY, -16, @Now), DATEADD(HOUR, -3, @Now))
    ) v ([list_key], [odoo_id], [name], [code], [company_id], [is_active], [data_json], [write_date], [synced_at])
    WHERE NOT EXISTS (SELECT 1 FROM [finance].[odoo_records] x WHERE x.[list_key] = v.[list_key] AND x.[odoo_id] = v.[odoo_id]);

    INSERT INTO [finance].[odoo_sync_runs]
        ([id], [mode], [triggered_by], [actor_user_id], [status], [counts_json], [error_message], [started_at], [finished_at])
    SELECT v.[id], v.[mode], v.[triggered_by], v.[actor_user_id], v.[status], v.[counts_json], v.[error_message], v.[started_at], v.[finished_at]
    FROM (VALUES
        ('a9130000000000000000000000000001', N'full', N'schedule', NULL, N'succeeded', N'{"companies":{"fetched":0,"added":0,"updated":0,"removed":0},"vendors":{"fetched":13,"added":13,"updated":0,"removed":0},"cost-centres":{"fetched":0,"added":0,"updated":0,"removed":0},"accounts":{"fetched":0,"added":0,"updated":0,"removed":0}}', NULL, DATEADD(MINUTE, -4, DATEADD(HOUR, -3, @Now)), DATEADD(HOUR, -3, @Now))
    ) v ([id], [mode], [triggered_by], [actor_user_id], [status], [counts_json], [error_message], [started_at], [finished_at])
    WHERE NOT EXISTS (SELECT 1 FROM [finance].[odoo_sync_runs] x WHERE x.[id] = v.[id]);

    /* ------------------------------------------------------------------
       Scan history: a daily scan, a period scan and a failed one. None open.
       ------------------------------------------------------------------ */
    INSERT INTO [finance].[invoice_scan_runs]
        ([id], [requested_by_user_id], [requested_by], [from_date], [to_date], [mailboxes_json], [status], [total_messages], [processed_messages], [invoice_emails], [other_emails], [duplicate_invoices], [errors], [created_date], [updated_date])
    SELECT v.[id], v.[requested_by_user_id], v.[requested_by], v.[from_date], v.[to_date], v.[mailboxes_json], v.[status], v.[total_messages], v.[processed_messages], v.[invoice_emails], v.[other_emails], v.[duplicate_invoices], v.[errors], v.[created_date], v.[updated_date]
    FROM (VALUES
        ('a9050000000000000000000000000001', NULL, N'Scheduled scan', CAST(NULL AS DATE), CAST(NULL AS DATE), N'["ap@tricab.com","ap.projects@sample.local"]', N'Complete', 6, 6, 4, 2, 0, 0, CASE WHEN DATEADD(MINUTE, -70, @Now) < @TodayStart THEN @TodayStart ELSE DATEADD(MINUTE, -70, @Now) END, CASE WHEN DATEADD(MINUTE, -66, @Now) < @TodayStart THEN @TodayStart ELSE DATEADD(MINUTE, -66, @Now) END),
