        ('a9090000000000000000000000000002', 'a9010000000000000000000000000020', NULL, NULL, 'a90a0000000000000000000000000002', (SELECT [UserId] FROM @Ids WHERE [Key] = N'lena'), N'Hi,' + NCHAR(10) + N'' + NCHAR(10) + N'Please send the purchase order number for invoice WG-6620.' + NCHAR(10) + N'' + NCHAR(10) + N'Regards,' + NCHAR(10) + N'Accounts Payable', 0, DATEADD(MINUTE, 700, DATEADD(DAY, -50, @TodayStart))),
        ('a9090000000000000000000000000003', NULL, 'a9020000000000000000000000000004', NULL, 'a90a0000000000000000000000000003', (SELECT [UserId] FROM @Ids WHERE [Key] = N'lena'), N'Hi,' + NCHAR(10) + N'' + NCHAR(10) + N'Thanks for getting in touch. Payment for BW-1180 is scheduled for the next payment run and you will see it shortly.' + NCHAR(10) + N'' + NCHAR(10) + N'Regards,' + NCHAR(10) + N'Accounts Payable', 0, CASE WHEN DATEADD(MINUTE, -20, @Now) < @TodayStart THEN @TodayStart ELSE DATEADD(MINUTE, -20, @Now) END),
