        ('a9090000000000000000000000000005', NULL, NULL, 'a9060000000000000000000000000001', 'a90a0000000000000000000000000005', (SELECT [UserId] FROM @Ids WHERE [Key] = N'mia'), N'Hi,' + NCHAR(10) + N'' + NCHAR(10) + N'Mia Ford has asked for your approval of 3 invoices (MF-5512, TC-3071, TC-2984).' + NCHAR(10) + N'' + NCHAR(10) + N'Regards,' + NCHAR(10) + N'Accounts Payable', 0, DATEADD(MINUTE, 765, DATEADD(DAY, -2, @TodayStart)))
