    FROM (VALUES
        ('a90b0000000000000000000000000001', (SELECT [UserId] FROM @Ids WHERE [Key] = N'admin'), (SELECT [Name] FROM @Ids WHERE [Key] = N'admin'), N'invoice_binned', N'invoice', N'a9010000000000000000000000000029', N'{"invoice_no":"PC-2199","vendor":"Pinecrest Cleaning Co"}', DATEADD(HOUR, -52, @Now)),
        ('a90b0000000000000000000000000002', (SELECT [UserId] FROM @Ids WHERE [Key] = N'admin'), (SELECT [Name] FROM @Ids WHERE [Key] = N'admin'), N'invoice_binned', N'invoice', N'a9010000000000000000000000000030', N'{"invoice_no":"LP-0430","vendor":"Larkspur Print and Copy"}', DATEADD(HOUR, -30, @Now)),
        ('a90b0000000000000000000000000003', (SELECT [UserId] FROM @Ids WHERE [Key] = N'admin'), (SELECT [Name] FROM @Ids WHERE [Key] = N'admin'), N'invoice_binned', N'invoice', N'a9010000000000000000000000000031', N'{"invoice_no":"TC-2800","vendor":"Tallow Creek Engineering"}', DATEADD(HOUR, -100, @Now)),
        ('a90b0000000000000000000000000004', (SELECT [UserId] FROM @Ids WHERE [Key] = N'admin'), (SELECT [Name] FROM @Ids WHERE [Key] = N'admin'), N'invoice_binned', N'invoice', N'a9010000000000000000000000000032', N'{"invoice_no":"AV-20841","vendor":"Alder & Vale Logistics Pty Ltd"}', DATEADD(HOUR, -20, @Now)),
        ('a90b0000000000000000000000000005', (SELECT [UserId] FROM @Ids WHERE [Key] = N'lena'), (SELECT [Name] FROM @Ids WHERE [Key] = N'lena'), N'duplicate_override', N'invoice', N'a9010000000000000000000000000011', N'{"reason":"Corrected copy of SP-2210, not a second invoice"}', DATEADD(MINUTE, 780, DATEADD(DAY, -18, @TodayStart))),
        ('a90b0000000000000000000000000006', (SELECT [UserId] FROM @Ids WHERE [Key] = N'lena'), (SELECT [Name] FROM @Ids WHERE [Key] = N'lena'), N'vendor_email_sent', N'invoice', N'a9010000000000000000000000000012', N'{"to":"accounts@marlow-freight.example.test","cc":null,"from":"ap@tricab.com","subject":"Query about invoice MF-5398","attached":true,"files":{}}', DATEADD(MINUTE, 700, DATEADD(DAY, -20, @TodayStart))),
        ('a90b0000000000000000000000000007', (SELECT [UserId] FROM @Ids WHERE [Key] = N'lena'), (SELECT [Name] FROM @Ids WHERE [Key] = N'lena'), N'email_reply_sent', N'email', N'a9020000000000000000000000000004', N'{"to":"accounts@brightwell-safety.example.test","cc":null,"subject":"Re: Where is our payment?","threaded":true}', CASE WHEN DATEADD(MINUTE, -20, @Now) < @TodayStart THEN @TodayStart ELSE DATEADD(MINUTE, -20, @Now) END),
        ('a90b0000000000000000000000000008', (SELECT [UserId] FROM @Ids WHERE [Key] = N'mia'), (SELECT [Name] FROM @Ids WHERE [Key] = N'mia'), N'approval_requested', N'approval_batch', N'a9060000000000000000000000000001', N'{"invoice_ids":{"0":"a9010000000000000000000000000005","1":"a9010000000000000000000000000006","2":"a9010000000000000000000000000014"},"notified":{"0":"owen.reed@sample.local"},"notification_warning":null}', DATEADD(MINUTE, 765, DATEADD(DAY, -2, @TodayStart))),
        ('a90b0000000000000000000000000009', (SELECT [UserId] FROM @Ids WHERE [Key] = N'owen'), (SELECT [Name] FROM @Ids WHERE [Key] = N'owen'), N'approval_approved', N'approval_batch', N'a9060000000000000000000000000002', N'{"approver_name":"Owen Reed","approver_email":"owen.reed@sample.local","comment":"Approved. Please schedule for the Friday payment run.","preparer_email":"mia.ford@sample.local","notification_warning":null}', DATEADD(MINUTE, 540, DATEADD(DAY, -8, @TodayStart))),
        ('a90b0000000000000000000000000010', (SELECT [UserId] FROM @Ids WHERE [Key] = N'admin'), (SELECT [Name] FROM @Ids WHERE [Key] = N'admin'), N'approval_rejected', N'approval_batch', N'a9060000000000000000000000000003', N'{"approver_name":"Sample Administrator","approver_email":"sample.admin@sample.local","comment":"The Marlow charge looks wrong and Ibis Creek has no purchase order. Query both first.","preparer_email":"mia.ford@sample.local","notification_warning":null}', DATEADD(MINUTE, 600, DATEADD(DAY, -22, @TodayStart)))
    ) v ([id], [actor_user_id], [actor_name], [action], [entity_type], [entity_id], [details], [created_date])
    WHERE NOT EXISTS (SELECT 1 FROM [finance].[invoice_audit_events] x WHERE x.[id] = v.[id]);

    /* ------------------------------------------------------------------
       Guard: the dataset is whole.
       ------------------------------------------------------------------ */
    IF (SELECT COUNT(*) FROM [finance].[invoice_invoices] WHERE [id] LIKE 'a901%' AND [deleted_at] IS NULL) <> 28
       OR (SELECT COUNT(*) FROM [finance].[invoice_invoices] WHERE [id] LIKE 'a901%' AND [deleted_at] IS NOT NULL) <> 4
       OR (SELECT COUNT(*) FROM [finance].[invoice_emails] WHERE [id] LIKE 'a902%') <> 26
       OR (SELECT COUNT(*) FROM [finance].[invoice_email_attachments] WHERE [id] LIKE 'a903%') <> 24
       OR (SELECT COUNT(*) FROM [finance].[attachments] WHERE [id] LIKE 'a904%') <> 22
       OR (SELECT COUNT(*) FROM [finance].[invoice_scan_runs] WHERE [id] LIKE 'a905%') <> 3
       OR (SELECT COUNT(*) FROM [finance].[invoice_approval_batches] WHERE [id] LIKE 'a906%') <> 3
       OR (SELECT COUNT(*) FROM [finance].[invoice_approval_items] WHERE [id] LIKE 'a907%') <> 8
       OR (SELECT COUNT(*) FROM [finance].[invoice_approval_decisions] WHERE [id] LIKE 'a908%') <> 2
       OR (SELECT COUNT(*) FROM [finance].[invoice_outbound_messages] WHERE [id] LIKE 'a909%') <> 5
       OR (SELECT COUNT(*) FROM [finance].[mail_deliveries] WHERE [id] LIKE 'a90a%') <> 5
       OR (SELECT COUNT(*) FROM [finance].[invoice_audit_events] WHERE [id] LIKE 'a90b%') <> 10
       OR (SELECT COUNT(*) FROM [finance].[invoice_scan_skips] WHERE [id] LIKE 'a90c%') <> 1
       OR (SELECT COUNT(*) FROM [finance].[odoo_records] WHERE [list_key] = N'vendors' AND [odoo_id] BETWEEN 101 AND 199) <> 13
    BEGIN
        THROW 54243, N'The Tri-AP sample data is not whole (32 invoices of which 4 binned, 26 emails, their attachments and files, 3 scan runs, 3 batches, 5 sent mails, the audit events and 13 vendors).', 1;
    END;

    SELECT
        (SELECT COUNT(*) FROM [finance].[invoice_invoices])         AS [Invoices],
        (SELECT COUNT(*) FROM [finance].[invoice_emails])           AS [Emails],
        (SELECT COUNT(*) FROM [finance].[invoice_email_attachments]) AS [EmailAttachments],
        (SELECT COUNT(*) FROM [finance].[attachments] WHERE [application_key] = N'AP') AS [Files],
        (SELECT COUNT(*) FROM [finance].[invoice_approval_batches]) AS [ApprovalBatches],
        (SELECT COUNT(*) FROM [finance].[invoice_outbound_messages]) AS [OutboundMessages],
        (SELECT COUNT(*) FROM [finance].[odoo_records] WHERE [list_key] = N'vendors') AS [Vendors];

    COMMIT TRANSACTION;

    PRINT N'Tri-AP sample data is in. Set FINANCE_AP_SAMPLE_FILES=true (with the in-memory blob store) to open the invoice documents.';
END TRY
BEGIN CATCH
    IF @@TRANCOUNT > 0
    BEGIN
        ROLLBACK TRANSACTION;
    END;

    DECLARE @ErrorMessage NVARCHAR(4000) = ERROR_MESSAGE();
    DECLARE @ErrorSeverity INT = ERROR_SEVERITY();
    DECLARE @ErrorState INT = ERROR_STATE();
    RAISERROR(@ErrorMessage, @ErrorSeverity, @ErrorState);
END CATCH;
